mapper.select:
select max(trade_date)
  from sector_fund_flow_daily_snapshots
 where deleted_at is null
   and scope = #{scope}

   and trade_date <= #{maxTradeDate}

select 
  from sector_fund_flow_daily_snapshots s
 where deleted_at is null
   and scope = #{scope}
   and trade_date = #{tradeDate}
 order by net desc nulls last, rank asc nulls last, sector_name asc
 limit #{limit}

with recent_dates as (
    select trade_date
      from (
        select distinct trade_date
          from sector_fund_flow_daily_snapshots
         where deleted_at is null
           and scope = #{scope}

           and trade_date <= #{maxTradeDate}

         order by trade_date desc
         limit #{days}
      ) d
),
ranked_rows as (
    select ,
           row_number() over (
               partition by trade_date
               order by net desc nulls last, rank asc nulls last, sector_name asc
           ) as row_no
      from sector_fund_flow_daily_snapshots s
     where s.deleted_at is null
       and s.scope = #{scope}
       and s.trade_date in (select trade_date from recent_dates)
)
select 
  from ranked_rows
 where row_no <= #{top}
 order by trade_date asc, row_no asc
